package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class ShapeDrawable extends Drawable { private android.graphics.drawable.shapes.Shape shape; private Paint paint=new Paint(); public ShapeDrawable(){} public ShapeDrawable(android.graphics.drawable.shapes.Shape s){shape=s;} public Paint getPaint(){return paint;} public void setShape(android.graphics.drawable.shapes.Shape s){shape=s;} public android.graphics.drawable.shapes.Shape getShape(){return shape;} public void draw(Canvas c){Rect r=getBounds();if(shape==null)c.drawRect(r,paint);else{shape.resize(r.width(),r.height());c.save();c.translate(r.left,r.top);shape.draw(c,paint);c.restore();}} }